R["csb-p7-rotate"] = "public class Solution\n{\n    public static int[] RotateLeft(int[] values, int k)\n    {\n        if (values == null) throw new ArgumentException(\"null input\");\n        int n = values.Length;\n        int[] result = new int[n];\n        for (int i = 0; i < n; i++)\n            result[(i - k % n + n) % n] = values[i];\n        return result;\n    }\n}\n";
W["csb-p7-rotate"] = "public class Solution\n{\n    public static int[] RotateLeft(int[] values, int k)\n    {\n        if (values == null) throw new ArgumentException(\"null input\");\n        int n = values.Length;\n        // near-miss: returns the input itself for k % n == 0 \u2014 an alias, so\n        // mutating the \"result\" corrupts the caller's array\n        if (k % n == 0) return values;\n        int[] result = new int[n];\n        for (int i = 0; i < n; i++)\n            result[(i - k % n + n) % n] = values[i];\n        return result;\n    }\n}\n";
R["csb-p7-reverse"] = "public class Solution\n{\n    public static void ReverseInPlace(int[] values)\n    {\n        if (values == null) return;\n        for (int i = 0, j = values.Length - 1; i < j; i++, j--)\n        {\n            (values[i], values[j]) = (values[j], values[i]);\n        }\n    }\n}\n";
W["csb-p7-reverse"] = "public class Solution\n{\n    public static void ReverseInPlace(int[] values)\n    {\n        if (values == null) return;\n        // near-miss: looping the FULL length swaps each pair twice \u2014 the\n        // second pass undoes the first, so the array comes back unchanged\n        for (int i = 0; i < values.Length; i++)\n        {\n            (values[i], values[values.Length - 1 - i]) = (values[values.Length - 1 - i], values[i]);\n        }\n    }\n}\n";
R["csb-checkpoint-m7-task"] = "public class Solution\n{\n    public static double[] MovingAverage(int[] readings, int window)\n    {\n        if (window < 1) throw new ArgumentException(\"window must be >= 1\");\n        if (readings == null) throw new ArgumentException(\"null readings\");\n        int n = readings.Length - window + 1;\n        if (n <= 0) return new double[0];\n        var result = new double[n];\n        for (int i = 0; i < n; i++)\n        {\n            long sum = 0;\n            for (int j = i; j < i + window; j++) sum += readings[j];\n            result[i] = (double)sum / window;\n        }\n        return result;\n    }\n\n    public static bool IsPalindrome(int[] values)\n    {\n        if (values == null) return false;\n        for (int i = 0, j = values.Length - 1; i < j; i++, j--)\n            if (values[i] != values[j]) return false;\n        return true;\n    }\n}\n";
W["csb-checkpoint-m7-task"] = "public class Solution\n{\n    public static double[] MovingAverage(int[] readings, int window)\n    {\n        if (window < 1) throw new ArgumentException(\"window must be >= 1\");\n        if (readings == null) throw new ArgumentException(\"null readings\");\n        int n = readings.Length - window + 1;\n        if (n <= 0) return new double[0];\n        var result = new double[n];\n        for (int i = 0; i < n; i++)\n        {\n            long sum = 0;\n            // near-miss: j <= i + window reads one element past the window \u2014\n            // for the last window this walks off the array and throws\n            for (int j = i; j <= i + window; j++) sum += readings[j];\n            result[i] = (double)sum / window;\n        }\n        return result;\n    }\n\n    public static bool IsPalindrome(int[] values)\n    {\n        // near-miss: null treated as palindrome \u2014 the contract says false\n        if (values == null) return true;\n        for (int i = 0, j = values.Length - 1; i < j; i++, j--)\n            if (values[i] != values[j]) return false;\n        return true;\n    }\n}\n";
R["csb-p8-wordcount"] = "public class Solution\n{\n    public static Dictionary<string, int> WordCounts(IEnumerable<string> words)\n    {\n        var result = new Dictionary<string, int>();\n        if (words == null) return result;\n        foreach (string w in words)\n        {\n            string key = w.ToLowerInvariant();\n            result.TryGetValue(key, out int n);\n            result[key] = n + 1;\n        }\n        return result;\n    }\n}\n";
W["csb-p8-wordcount"] = "public class Solution\n{\n    public static Dictionary<string, int> WordCounts(IEnumerable<string> words)\n    {\n        var result = new Dictionary<string, int>();\n        if (words == null) return result;\n        foreach (string w in words)\n        {\n            // near-miss: stores the ORIGINAL casing as the key, so \"B\" and\n            // \"b\" become separate entries and lowercase lookups miss\n            result.TryGetValue(w, out int n);\n            result[w] = n + 1;\n        }\n        return result;\n    }\n}\n";
R["csb-p8-dedupe"] = "public class Solution\n{\n    public static List<string> Dedupe(IEnumerable<string> items)\n    {\n        var result = new List<string>();\n        if (items == null) return result;\n        var seen = new HashSet<string>();\n        foreach (string s in items)\n        {\n            if (seen.Add(s)) result.Add(s);   // Add returns false on duplicate\n        }\n        return result;\n    }\n}\n";
W["csb-p8-dedupe"] = "public class Solution\n{\n    public static List<string> Dedupe(IEnumerable<string> items)\n    {\n        var result = new List<string>();\n        if (items == null) return result;\n        // near-miss: case-INSENSITIVE membership \u2014 \"A\" gets swallowed as a\n        // duplicate of \"a\", breaking the keep-original-casing contract\n        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);\n        foreach (string s in items)\n        {\n            if (seen.Add(s)) result.Add(s);\n        }\n        return result;\n    }\n}\n";
R["csb-p8-indexmap"] = "public class Solution\n{\n    public static Dictionary<string, int> LastIndex(IEnumerable<string> items)\n    {\n        var result = new Dictionary<string, int>();\n        if (items == null) return result;\n        int i = 0;\n        foreach (string s in items)\n        {\n            result[s] = i;   // later occurrence overwrites\n            i++;\n        }\n        return result;\n    }\n}\n";
W["csb-p8-indexmap"] = "public class Solution\n{\n    public static Dictionary<string, int> LastIndex(IEnumerable<string> items)\n    {\n        var result = new Dictionary<string, int>();\n        if (items == null) return result;\n        int i = 0;\n        foreach (string s in items)\n        {\n            // near-miss: Add instead of indexer \u2014 a duplicate key throws\n            // ArgumentException, so any repeated item crashes the build\n            result.Add(s, i);\n            i++;\n        }\n        return result;\n    }\n}\n";
R["csb-p8-inventory"] = "public class Solution\n{\n    public static Dictionary<string, int> ApplySales(Dictionary<string, int> stock, IEnumerable<(string Sku, int Qty)> sales)\n    {\n        foreach (var sale in sales)\n        {\n            if (!stock.TryGetValue(sale.Sku, out int have))\n                throw new InvalidOperationException($\"unknown sku {sale.Sku}\");\n            if (sale.Qty > have)\n                throw new InvalidOperationException($\"insufficient stock for {sale.Sku}\");\n            stock[sale.Sku] = have - sale.Qty;\n        }\n        return stock;\n    }\n}\n";
W["csb-p8-inventory"] = "public class Solution\n{\n    public static Dictionary<string, int> ApplySales(Dictionary<string, int> stock, IEnumerable<(string Sku, int Qty)> sales)\n    {\n        foreach (var sale in sales)\n        {\n            if (!stock.TryGetValue(sale.Sku, out int have))\n                throw new InvalidOperationException($\"unknown sku {sale.Sku}\");\n            // near-miss: no sufficiency check at all - stock silently goes\n            // negative instead of refusing the sale\n            stock[sale.Sku] = have - sale.Qty;\n        }\n        return stock;\n    }\n}\n";
R["csb-checkpoint-m8-task"] = "public class Solution\n{\n    public static Dictionary<string, double> Averages(Dictionary<string, List<int>> gradebook)\n    {\n        var result = new Dictionary<string, double>();\n        if (gradebook == null) return result;\n        foreach (var kv in gradebook)\n        {\n            if (kv.Value == null || kv.Value.Count == 0) continue;\n            long sum = 0;\n            foreach (int s in kv.Value) sum += s;\n            result[kv.Key] = (double)sum / kv.Value.Count;\n        }\n        return result;\n    }\n\n    public static List<string> Honors(Dictionary<string, List<int>> gradebook)\n    {\n        var av = Averages(gradebook);\n        var names = new List<string>(av.Keys);\n        names.Sort((a, b) =>\n        {\n            int byAvg = av[b].CompareTo(av[a]);\n            return byAvg != 0 ? byAvg : string.CompareOrdinal(a, b);\n        });\n        return names.Where(n => av[n] >= 90.0).ToList();\n    }\n\n    public static string TopStudent(Dictionary<string, List<int>> gradebook)\n    {\n        var av = Averages(gradebook);\n        if (av.Count == 0) return \"\";\n        string best = null;\n        foreach (var kv in av)\n        {\n            if (best == null\n                || kv.Value > av[best]\n                || (kv.Value == av[best] && string.CompareOrdinal(kv.Key, best) < 0))\n                best = kv.Key;\n        }\n        return best;\n    }\n}\n";
W["csb-checkpoint-m8-task"] = "public class Solution\n{\n    public static Dictionary<string, double> Averages(Dictionary<string, List<int>> gradebook)\n    {\n        var result = new Dictionary<string, double>();\n        if (gradebook == null) return result;\n        foreach (var kv in gradebook)\n        {\n            // near-miss: does NOT skip empty score lists \u2014 an empty list makes\n            // sum 0 / count 0, which throws DivideByZeroException\n            long sum = 0;\n            foreach (int s in kv.Value) sum += s;\n            result[kv.Key] = (double)sum / kv.Value.Count;\n        }\n        return result;\n    }\n\n    public static List<string> Honors(Dictionary<string, List<int>> gradebook)\n    {\n        // near-miss: ascending name only, ignoring the average ordering\n        var av = Averages(gradebook);\n        var names = new List<string>(av.Keys);\n        names.Sort(string.CompareOrdinal);\n        return names.Where(n => av[n] >= 90.0).ToList();\n    }\n\n    public static string TopStudent(Dictionary<string, List<int>> gradebook)\n    {\n        // near-miss: breaks ties by REVERSE alphabetical \u2014 \"mai\" beats \"hoa\"\n        var av = Averages(gradebook);\n        if (av.Count == 0) return \"\";\n        string best = null;\n        foreach (var kv in av)\n        {\n            if (best == null\n                || kv.Value > av[best]\n                || (kv.Value == av[best] && string.CompareOrdinal(kv.Key, best) > 0))\n                best = kv.Key;\n        }\n        return best;\n    }\n}\n";
