R["csb-p9-rectangle"] = "public class Solution\n{\n    public sealed class Rectangle\n    {\n        private double width;\n        private double height;\n        public Rectangle(double width, double height)\n        {\n            if (width <= 0 || height <= 0)\n                throw new ArgumentException(\"dimensions must be positive\");\n            this.width = width;\n            this.height = height;\n        }\n        public double Width { get { return width; } }\n        public double Height { get { return height; } }\n        public double Area() { return width * height; }\n        public void Scale(double factor)\n        {\n            if (factor <= 0)\n                throw new ArgumentException(\"factor must be positive\");\n            width *= factor;\n            height *= factor;\n        }\n    }\n}\n";
W["csb-p9-rectangle"] = "public class Solution\n{\n    public sealed class Rectangle\n    {\n        private double width;\n        private double height;\n        public Rectangle(double width, double height)\n        {\n            if (width <= 0 || height <= 0)\n                throw new ArgumentException(\"dimensions must be positive\");\n            this.width = width;\n            this.height = height;\n        }\n        public double Width { get { return width; } }\n        public double Height { get { return height; } }\n        public double Area() { return width * height; }\n        public void Scale(double factor)\n        {\n            if (factor <= 0)\n                throw new ArgumentException(\"factor must be positive\");\n            width *= factor;\n            // near-miss: scales only the width \u2014 height is untouched, so\n            // Area() after Scale(2) is 2x instead of 4x\n        }\n    }\n}\n";
