W["csb-p9-temperature"] = "public class Solution\n{\n    public sealed class Temperature\n    {\n        private const double AbsoluteZeroC = -273.15;\n        private double celsius;\n        public Temperature(double celsius)\n        {\n            if (celsius < AbsoluteZeroC)\n                throw new ArgumentException(\"below absolute zero\");\n            this.celsius = celsius;\n        }\n        public double Celsius { get { return celsius; } }\n        public static Temperature FromFahrenheit(double f)\n        {\n            // near-miss: swapped ratio \u2014 multiplies by 9/5 instead of 5/9,\n            // so 212F yields 324C, not the boiling point 100C\n            return new Temperature((f - 32.0) * 9.0 / 5.0);\n        }\n    }\n}\n";
R["csb-p9-player"] = "public class Solution\n{\n    public sealed class Player\n    {\n        private int health = 100;\n        public Player(string name)\n        {\n            if (string.IsNullOrWhiteSpace(name))\n                throw new ArgumentException(\"name required\");\n            Name = name;\n        }\n        public string Name { get; }\n        public int Health { get { return health; } }\n        public bool IsAlive { get { return health > 0; } }\n        public void TakeDamage(int amount)\n        {\n            if (amount < 0) throw new ArgumentException(\"negative damage\");\n            health = Math.Max(0, health - amount);\n        }\n        public void Heal(int amount)\n        {\n            if (amount < 0) throw new ArgumentException(\"negative heal\");\n            health = Math.Min(100, health + amount);\n        }\n    }\n}\n";
W["csb-p9-player"] = "public class Solution\n{\n    public sealed class Player\n    {\n        private int health = 100;\n        public Player(string name)\n        {\n            if (string.IsNullOrWhiteSpace(name))\n                throw new ArgumentException(\"name required\");\n            Name = name;\n        }\n        public string Name { get; }\n        public int Health { get { return health; } }\n        public bool IsAlive { get { return health > 0; } }\n        public void TakeDamage(int amount)\n        {\n            if (amount < 0) throw new ArgumentException(\"negative damage\");\n            health = Math.Max(0, health - amount);\n        }\n        public void Heal(int amount)\n        {\n            if (amount < 0) throw new ArgumentException(\"negative heal\");\n            // near-miss: no upper clamp \u2014 healing past 100 pushes health\n            // beyond the [0, 100] contract\n            health = health + amount;\n        }\n    }\n}\n";
R["csb-checkpoint-m9-task"] = "public class Solution\n{\n    public sealed class BankAccount\n    {\n        private decimal balance;\n        public BankAccount(string owner, decimal openingBalance)\n        {\n            if (string.IsNullOrWhiteSpace(owner))\n                throw new ArgumentException(\"owner required\");\n            if (openingBalance < 0)\n                throw new ArgumentException(\"negative opening balance\");\n            Owner = owner;\n            balance = openingBalance;\n        }\n        public string Owner { get; }\n        public decimal Balance { get { return balance; } }\n        public void Deposit(decimal amount)\n        {\n            if (amount <= 0)\n                throw new ArgumentException(\"non-positive deposit\");\n            balance += amount;\n        }\n        public void Withdraw(decimal amount)\n        {\n            if (amount <= 0)\n                throw new ArgumentException(\"non-positive withdrawal\");\n            if (amount > balance)\n                throw new InvalidOperationException(\"insufficient funds\");\n            balance -= amount;\n        }\n    }\n}\n";
W["csb-checkpoint-m9-task"] = "public class Solution\n{\n    public sealed class BankAccount\n    {\n        private decimal balance;\n        public BankAccount(string owner, decimal openingBalance)\n        {\n            if (string.IsNullOrWhiteSpace(owner))\n                throw new ArgumentException(\"owner required\");\n            if (openingBalance < 0)\n                throw new ArgumentException(\"negative opening balance\");\n            Owner = owner;\n            balance = openingBalance;\n        }\n        public string Owner { get; }\n        public decimal Balance { get { return balance; } }\n        public void Deposit(decimal amount)\n        {\n            // near-miss: no positivity guard \u2014 a \"deposit\" of -100 silently\n            // drains the account, and 0 counts as business as usual\n            balance += amount;\n        }\n        public void Withdraw(decimal amount)\n        {\n            if (amount <= 0)\n                throw new ArgumentException(\"non-positive withdrawal\");\n            if (amount > balance)\n                throw new InvalidOperationException(\"insufficient funds\");\n            balance -= amount;\n        }\n    }\n}\n";
