R["csb-checkpoint-m10-task"] = "public class Solution\n{\n    public abstract class MediaItem\n    {\n        public MediaItem(string title)\n        {\n            if (string.IsNullOrWhiteSpace(title))\n                throw new ArgumentException(\"title required\");\n            Title = title;\n        }\n        public string Title { get; }\n        public abstract int PlaySeconds();\n    }\n    public sealed class Song : MediaItem\n    {\n        private int seconds;\n        public Song(string title, int seconds) : base(title) { this.seconds = seconds; }\n        public override int PlaySeconds() { return seconds; }\n    }\n    public sealed class Video : MediaItem\n    {\n        private int seconds;\n        private int speed;\n        public Video(string title, int seconds, int speed) : base(title) { this.seconds = seconds; this.speed = speed; }\n        public override int PlaySeconds() { return seconds / speed; }\n    }\n    public static int TotalRuntime(List<MediaItem> items)\n    {\n        if (items == null) return 0;\n        int total = 0;\n        foreach (MediaItem m in items) total += m.PlaySeconds();\n        return total;\n    }\n}\n";
W["csb-checkpoint-m10-task"] = "public class Solution\n{\n    public abstract class MediaItem\n    {\n        public MediaItem(string title)\n        {\n            if (string.IsNullOrWhiteSpace(title))\n                throw new ArgumentException(\"title required\");\n            Title = title;\n        }\n        public string Title { get; }\n        public abstract int PlaySeconds();\n    }\n    public sealed class Song : MediaItem\n    {\n        private int seconds;\n        public Song(string title, int seconds) : base(title) { this.seconds = seconds; }\n        public override int PlaySeconds() { return seconds; }\n    }\n    public sealed class Video : MediaItem\n    {\n        private int seconds;\n        private int speed;\n        public Video(string title, int seconds, int speed) : base(title) { this.seconds = seconds; this.speed = speed; }\n        // near-miss: ignores playback speed \u2014 every video counts at 1x, so\n        // a 2x video reports double its wall-clock time\n        public override int PlaySeconds() { return seconds; }\n    }\n    public static int TotalRuntime(List<MediaItem> items)\n    {\n        if (items == null) return 0;\n        int total = 0;\n        foreach (MediaItem m in items) total += m.PlaySeconds();\n        return total;\n    }\n}\n";
