W["csb-p11-statusflow"] = "public class Solution\n{\n    public enum OrderStatus { Pending, Paid, Shipped, Cancelled }\n    public static OrderStatus? NextStatus(OrderStatus current)\n    {\n        // near-miss: treats Cancelled as if it still needed payment \u2014 the\n        // terminal state incorrectly advances to Paid\n        if (current == OrderStatus.Cancelled) return OrderStatus.Paid;\n        switch (current)\n        {\n            case OrderStatus.Pending: return OrderStatus.Paid;\n            case OrderStatus.Paid: return OrderStatus.Shipped;\n            default: return null;\n        }\n    }\n}\n";
