R["csb-p11-shipment"] = "public class Solution\n{\n    public enum Carrier { Air, Sea, Ground }\n    public sealed record Shipment(string Id, Carrier Via);\n    public static int Days(Carrier c)\n    {\n        if (!Enum.IsDefined(typeof(Carrier), c))\n            throw new ArgumentException(\"undefined carrier\");\n        switch (c)\n        {\n            case Carrier.Air: return 1;\n            case Carrier.Sea: return 5;\n            case Carrier.Ground: return 3;\n            default: throw new ArgumentException(\"undefined carrier\");\n        }\n    }\n    public static Carrier Fastest(Carrier a, Carrier b) { return Days(a) <= Days(b) ? a : b; }\n}\n";
W["csb-p11-shipment"] = "public class Solution\n{\n    public enum Carrier { Air, Sea, Ground }\n    public sealed record Shipment(string Id, Carrier Via);\n    public static int Days(Carrier c)\n    {\n        switch (c)\n        {\n            case Carrier.Air: return 1;\n            case Carrier.Sea: return 5;\n            case Carrier.Ground: return 3;\n            default: throw new ArgumentException(\"undefined carrier\");\n        }\n    }\n    public static Carrier Fastest(Carrier a, Carrier b)\n    {\n        // near-miss: swapped comparison \u2014 returns the SLOWER carrier\n        return Days(a) > Days(b) ? a : b;\n    }\n}\n";
R["csb-p11-batch"] = "public class Solution\n{\n    public struct Batch { public int Count; }\n    public sealed class BatchRef { public int Count; }\n    public static (int First, int Second) CopyProbe()\n    {\n        var b1 = new Batch { Count = 1 };\n        var b2 = b1;\n        b2.Count = 2;\n        return (b1.Count, b2.Count);\n    }\n    public static (int First, int Second) RefProbe()\n    {\n        var r1 = new BatchRef { Count = 1 };\n        var r2 = r1;\n        r2.Count = 2;\n        return (r1.Count, r2.Count);\n    }\n}\n";
W["csb-p11-batch"] = "public class Solution\n{\n    public struct Batch { public int Count; }\n    public sealed class BatchRef { public int Count; }\n    public static (int First, int Second) CopyProbe()\n    {\n        var b1 = new Batch { Count = 1 };\n        var b2 = b1;\n        b2.Count = 2;\n        return (b1.Count, b2.Count);\n    }\n    public static (int First, int Second) RefProbe()\n    {\n        var r1 = new BatchRef { Count = 1 };\n        var r2 = r1;\n        // near-miss: replaces the reference instead of writing through it -\n        // the shared object is never mutated, so RefProbe reports 1,2 and\n        // fails to demonstrate class sharing\n        r2 = new BatchRef { Count = 2 };\n        // near-miss: \"fixes\" sharing by re-assigning r2 to a fresh object \u2014\n        // so the original escapes unmutated and RefProbe reports 1,2\n        r2 = new BatchRef { Count = 2 };\n        return (r1.Count, r2.Count);\n    }\n}\n";
R["csb-checkpoint-m11-task"] = "public class Solution\n{\n    public enum Category { Books, Electronics, Food }\n    public sealed record Item(string Name, Category Cat, decimal Price);\n    public static decimal Total(List<Item> items, Category cat)\n    {\n        if (items == null) return 0m;\n        decimal sum = 0m;\n        foreach (Item it in items)\n        {\n            if (it.Cat == cat) sum += it.Price;\n        }\n        return sum;\n    }\n    public static Item MostExpensive(List<Item> items)\n    {\n        if (items == null || items.Count == 0) return null;\n        Item best = items[0];\n        foreach (Item it in items)\n        {\n            if (it.Price > best.Price) best = it;\n        }\n        return best;\n    }\n}\n";
W["csb-checkpoint-m11-task"] = "public class Solution\n{\n    public enum Category { Books, Electronics, Food }\n    public sealed record Item(string Name, Category Cat, decimal Price);\n    public static decimal Total(List<Item> items, Category cat)\n    {\n        if (items == null) return 0m;\n        decimal sum = 0m;\n        foreach (Item it in items)\n        {\n            // near-miss: compares the enum by its int VALUE instead of the\n            // member \u2014 still works here, but the real defect: adds every\n            // item's price regardless of category\n            sum += it.Price;\n        }\n        return sum;\n    }\n    public static Item MostExpensive(List<Item> items)\n    {\n        if (items == null || items.Count == 0) return null;\n        Item best = items[0];\n        foreach (Item it in items)\n        {\n            if (it.Price > best.Price) best = it;\n        }\n        return best;\n    }\n}\n";
R["csb-p12-swap"] = "public class Solution\n{\n    public static void Swap<T>(T[] items, int i, int j)\n    {\n        if (i < 0 || i >= items.Length || j < 0 || j >= items.Length)\n            throw new ArgumentOutOfRangeException(\"index out of range\");\n        T tmp = items[i];\n        items[i] = items[j];\n        items[j] = tmp;\n    }\n    public static T[] Reversed<T>(T[] items)\n    {\n        if (items == null || items.Length == 0)\n            return new T[0];\n        var result = new T[items.Length];\n        for (int i = 0; i < items.Length; i++)\n            result[i] = items[items.Length - 1 - i];\n        return result;\n    }\n}\n";
W["csb-p12-swap"] = "public class Solution\n{\n    public static void Swap<T>(T[] items, int i, int j)\n    {\n        if (i < 0 || i >= items.Length || j < 0 || j >= items.Length)\n            throw new ArgumentOutOfRangeException(\"index out of range\");\n        T tmp = items[i];\n        items[i] = items[j];\n        items[j] = tmp;\n    }\n    public static T[] Reversed<T>(T[] items)\n    {\n        if (items == null || items.Length == 0)\n            return new T[0];\n        // near-miss: reverses IN PLACE and returns the same array \u2014 the\n        // caller's data is silently mutated, breaking the new-array contract\n        for (int i = 0; i < items.Length / 2; i++)\n        {\n            T tmp = items[i];\n            items[i] = items[items.Length - 1 - i];\n            items[items.Length - 1 - i] = tmp;\n        }\n        return items;\n    }\n}\n";
