R["csb-p12-pairstore"] = "public class Solution\n{\n    public sealed class PairStore<T>\n    {\n        private readonly List<T> items = new List<T>();\n        public int Count { get { return items.Count; } }\n        public void Add(T item) { items.Add(item); }\n        public T Get(int index)\n        {\n            if (index < 0 || index >= items.Count)\n                throw new ArgumentOutOfRangeException(\"index out of range\");\n            return items[index];\n        }\n        public void Clear() { items.Clear(); }\n    }\n}\n";
W["csb-p12-pairstore"] = "public class Solution\n{\n    public sealed class PairStore<T>\n    {\n        private readonly List<T> items = new List<T>();\n        public int Count { get { return items.Count; } }\n        public void Add(T item) { items.Add(item); }\n        public T Get(int index)\n        {\n            if (index < 0 || index >= items.Count)\n                throw new ArgumentOutOfRangeException(\"index out of range\");\n            // near-miss: off-by-one \u2014 reads the slot AFTER the requested\n            // index, so Get(0) yields the second item\n            return items[index + 1];\n        }\n        public void Clear() { items.Clear(); }\n    }\n}\n";
R["csb-p12-maxof"] = "public class Solution\n{\n    public static T MaxOf<T>(IEnumerable<T> items) where T : IComparable<T>\n    {\n        if (items == null)\n            throw new InvalidOperationException(\"no elements\");\n        bool any = false;\n        T best = default;\n        foreach (T item in items)\n        {\n            if (!any) { best = item; any = true; }\n            else if (item.CompareTo(best) > 0) best = item;\n        }\n        if (!any)\n            throw new InvalidOperationException(\"no elements\");\n        return best;\n    }\n}\n";
W["csb-p12-maxof"] = "public class Solution\n{\n    public static T MaxOf<T>(IEnumerable<T> items) where T : IComparable<T>\n    {\n        if (items == null)\n            throw new InvalidOperationException(\"no elements\");\n        bool any = false;\n        T best = default;\n        foreach (T item in items)\n        {\n            if (!any) { best = item; any = true; }\n            // near-miss: comparison flipped \u2014 returns the MINIMUM, not the\n            // maximum; a discriminating test catches it immediately\n            else if (item.CompareTo(best) < 0) best = item;\n        }\n        if (!any)\n            throw new InvalidOperationException(\"no elements\");\n        return best;\n    }\n}\n";
R["csb-checkpoint-m12-task"] = "public class Solution\n{\n    public sealed class Repository<T> where T : IComparable<T>\n    {\n        private readonly List<T> items = new List<T>();\n        public int Count { get { return items.Count; } }\n        public void Add(T item) { items.Add(item); }\n        public T Get(int index)\n        {\n            if (index < 0 || index >= items.Count)\n                throw new ArgumentOutOfRangeException(\"index out of range\");\n            return items[index];\n        }\n        public bool Remove(T item)\n        {\n            for (int i = 0; i < items.Count; i++)\n            {\n                if (EqualityComparer<T>.Default.Equals(items[i], item))\n                {\n                    items.RemoveAt(i);\n                    return true;\n                }\n            }\n            return false;\n        }\n        public T Min()\n        {\n            if (items.Count == 0)\n                throw new InvalidOperationException(\"empty\");\n            T best = items[0];\n            foreach (T item in items)\n            {\n                if (item.CompareTo(best) < 0) best = item;\n            }\n            return best;\n        }\n        public List<T> Sorted()\n        {\n            var copy = new List<T>(items);\n            copy.Sort();\n            return copy;\n        }\n    }\n}\n";
W["csb-checkpoint-m12-task"] = "public class Solution\n{\n    public sealed class Repository<T> where T : IComparable<T>\n    {\n        private readonly List<T> items = new List<T>();\n        public int Count { get { return items.Count; } }\n        public void Add(T item) { items.Add(item); }\n        public T Get(int index)\n        {\n            if (index < 0 || index >= items.Count)\n                throw new ArgumentOutOfRangeException(\"index out of range\");\n            return items[index];\n        }\n        public bool Remove(T item)\n        {\n            for (int i = 0; i < items.Count; i++)\n            {\n                if (EqualityComparer<T>.Default.Equals(items[i], item))\n                {\n                    items.RemoveAt(i);\n                    return true;\n                }\n            }\n            return false;\n        }\n        public T Min()\n        {\n            if (items.Count == 0)\n                throw new InvalidOperationException(\"empty\");\n            T best = items[0];\n            foreach (T item in items)\n            {\n                if (item.CompareTo(best) < 0) best = item;\n            }\n            return best;\n        }\n        public List<T> Sorted()\n        {\n            // near-miss: sorts the backing list in place \u2014 the store's\n            // insertion order is destroyed as a side effect\n            items.Sort();\n            return items;\n        }\n    }\n}\n";
R["csb-p13-parseage"] = "public class Solution\n{\n    public static int ParseAge(string input)\n    {\n        if (string.IsNullOrWhiteSpace(input))\n            throw new ArgumentException(\"input required\");\n        if (!int.TryParse(input, out int age))\n            throw new FormatException(\"not a number\");\n        if (age < 0 || age > 150)\n            throw new ArgumentOutOfRangeException(\"implausible age\");\n        return age;\n    }\n}\n";
W["csb-p13-parseage"] = "public class Solution\n{\n    public static int ParseAge(string input)\n    {\n        if (string.IsNullOrWhiteSpace(input))\n            throw new ArgumentException(\"input required\");\n        if (!int.TryParse(input, out int age))\n            throw new FormatException(\"not a number\");\n        // near-miss: range check uses AND instead of OR \u2014 \"-1\" parses to a\n        // negative age that fails neither side of (age < 0 && age > 150)\n        if (age < 0 && age > 150)\n            throw new ArgumentOutOfRangeException(\"implausible age\");\n        return age;\n    }\n}\n";
R["csb-p13-atm"] = "public class Solution\n{\n    public sealed class InsufficientFundsException : Exception\n    {\n        public decimal Missing { get; }\n        public InsufficientFundsException(decimal missing)\n            : base($\"insufficient funds: missing {missing}\")\n        {\n            Missing = missing;\n        }\n    }\n    public static decimal Withdraw(decimal balance, decimal amount)\n    {\n        if (amount <= 0)\n            throw new ArgumentException(\"amount must be positive\");\n        if (amount > balance)\n            throw new InsufficientFundsException(amount - balance);\n        return balance - amount;\n    }\n}\n";
W["csb-p13-atm"] = "public class Solution\n{\n    public sealed class InsufficientFundsException : Exception\n    {\n        public decimal Missing { get; }\n        public InsufficientFundsException(decimal missing)\n            : base($\"insufficient funds: missing {missing}\")\n        {\n            Missing = missing;\n        }\n    }\n    public static decimal Withdraw(decimal balance, decimal amount)\n    {\n        if (amount <= 0)\n            throw new ArgumentException(\"amount must be positive\");\n        // near-miss: Missing stores the requested amount, not the shortfall\n        if (amount > balance)\n            throw new InsufficientFundsException(amount);\n        return balance - amount;\n    }\n}\n";
R["csb-p13-retry"] = "public class Solution\n{\n    public static int ReadWithRetry(Func<int> reader, int attempts)\n    {\n        if (attempts <= 0)\n            throw new ArgumentException(\"attempts must be positive\");\n        for (int i = 0; i < attempts; i++)\n        {\n            try\n            {\n                return reader();\n            }\n            catch (InvalidOperationException)\n            {\n                // fall through to the next attempt\n            }\n        }\n        throw new InvalidOperationException(\"all attempts exhausted\");\n    }\n}\n";
W["csb-p13-retry"] = "public class Solution\n{\n    public static int ReadWithRetry(Func<int> reader, int attempts)\n    {\n        if (attempts <= 0)\n            throw new ArgumentException(\"attempts must be positive\");\n        // near-miss: loop runs attempts-1 times \u2014 the budget is spent one\n        // call short, so a reader that succeeds on the LAST allowed attempt\n        // still gets exhausted\n        for (int i = 0; i < attempts - 1; i++)\n        {\n            try\n            {\n                return reader();\n            }\n            catch (InvalidOperationException)\n            {\n            }\n        }\n        throw new InvalidOperationException(\"all attempts exhausted\");\n    }\n}\n";
