W["csb-p13-transfer"] = "public class Solution\n{\n    public static decimal Transfer(decimal from, decimal to, decimal amount)\n    {\n        if (amount <= 0)\n            throw new ArgumentException(\"amount must be positive\");\n        if (amount > from)\n            throw new InvalidOperationException(\"insufficient funds\");\n        return to + amount;\n    }\n    public static bool AuditTrail(List<string> log, Action action)\n    {\n        // near-miss: cleanup lives in a catch, not a finally \u2014 when action\n        // succeeds, \"done\" is never appended and the audit trail is silent\n        try\n        {\n            action();\n            return true;\n        }\n        catch (Exception)\n        {\n            log.Add(\"done\");\n            throw;\n        }\n    }\n}\n";
R["csb-checkpoint-m13-task"] = "public class Solution\n{\n    public sealed class BookingConflictException : Exception\n    {\n        public string Slot { get; }\n        public BookingConflictException(string slot, string message) : base(message)\n        {\n            Slot = slot;\n        }\n    }\n    public static string Book(List<string> takenSlots, string slot)\n    {\n        if (string.IsNullOrWhiteSpace(slot))\n            throw new ArgumentException(\"slot required\");\n        if (takenSlots.Contains(slot))\n            throw new BookingConflictException(slot, $\"slot {slot} already booked\");\n        takenSlots.Add(slot);\n        return slot;\n    }\n    public static T Guard<T>(Func<T> action, string label)\n    {\n        if (label == null)\n            throw new ArgumentException(\"label required\");\n        try\n        {\n            return action();\n        }\n        catch (InvalidOperationException ex)\n        {\n            throw new InvalidOperationException($\"{label}: {ex.Message}\");\n        }\n    }\n}\n";
W["csb-checkpoint-m13-task"] = "public class Solution\n{\n    public sealed class BookingConflictException : Exception\n    {\n        public string Slot { get; }\n        public BookingConflictException(string slot, string message) : base(message)\n        {\n            Slot = slot;\n        }\n    }\n    public static string Book(List<string> takenSlots, string slot)\n    {\n        if (string.IsNullOrWhiteSpace(slot))\n            throw new ArgumentException(\"slot required\");\n        if (takenSlots.Contains(slot))\n            throw new BookingConflictException(slot, $\"slot {slot} already booked\");\n        takenSlots.Add(slot);\n        return slot;\n    }\n    public static T Guard<T>(Func<T> action, string label)\n    {\n        if (label == null)\n            throw new ArgumentException(\"label required\");\n        // near-miss: catches EVERYTHING \u2014 foreign exception types are\n        // re-wrapped as InvalidOperationException, erasing their identity\n        try\n        {\n            return action();\n        }\n        catch (Exception ex)\n        {\n            throw new InvalidOperationException($\"{label}: {ex.Message}\");\n        }\n    }\n}\n";
