R["csb-p14-csv"] = "public class Solution\n{\n    public static void SaveScores(string path, List<(int Id, string Name, int Score)> rows)\n    {\n        string dir = Path.GetDirectoryName(path);\n        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);\n        File.WriteAllLines(path, rows.Select(r => $\"{r.Id}|{r.Name}|{r.Score}\").ToArray());\n    }\n    public static List<(int Id, string Name, int Score)> LoadScores(string path)\n    {\n        var result = new List<(int, string, int)>();\n        if (!File.Exists(path)) return result;\n        foreach (string line in File.ReadAllLines(path))\n        {\n            string[] p = line.Split('|');\n            result.Add((int.Parse(p[0]), p[1], int.Parse(p[2])));\n        }\n        return result;\n    }\n}\n";
W["csb-p14-csv"] = "public class Solution\n{\n    public static void SaveScores(string path, List<(int Id, string Name, int Score)> rows)\n    {\n        string dir = Path.GetDirectoryName(path);\n        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);\n        File.WriteAllLines(path, rows.Select(r => $\"{r.Id}|{r.Name}|{r.Score}\").ToArray());\n    }\n    public static List<(int Id, string Name, int Score)> LoadScores(string path)\n    {\n        var result = new List<(int, string, int)>();\n        if (!File.Exists(path)) return result;\n        foreach (string line in File.ReadAllLines(path))\n        {\n            string[] p = line.Split('|');\n            // near-miss: swaps name and score on parse \u2014 ids load, scores\n            // land in the name slot, and round-trip tests expose it\n            result.Add((int.Parse(p[0]), p[2], int.Parse(p[1])));\n        }\n        return result;\n    }\n}\n";
R["csb-p14-corrupt"] = "public class Solution\n{\n    public static (int Loaded, int Skipped) LoadScoresLenient(string path, List<(int Id, string Name, int Score)> into)\n    {\n        int loaded = 0, skipped = 0;\n        if (!File.Exists(path)) return (0, 0);\n        foreach (string line in File.ReadAllLines(path))\n        {\n            string[] p = line.Split('|');\n            if (p.Length != 3 || !int.TryParse(p[0], out int id) || !int.TryParse(p[2], out int score))\n            {\n                skipped++;\n                continue;\n            }\n            into.Add((id, p[1], score));\n            loaded++;\n        }\n        return (loaded, skipped);\n    }\n}\n";
W["csb-p14-corrupt"] = "public class Solution\n{\n    public static (int Loaded, int Skipped) LoadScoresLenient(string path, List<(int Id, string Name, int Score)> into)\n    {\n        int loaded = 0, skipped = 0;\n        if (!File.Exists(path)) return (0, 0);\n        foreach (string line in File.ReadAllLines(path))\n        {\n            string[] p = line.Split('|');\n            // near-miss: checks the field count but not the numbers \u2014\n            // int.Parse on \"abc\" throws and kills the whole load\n            if (p.Length != 3)\n            {\n                skipped++;\n                continue;\n            }\n            into.Add((int.Parse(p[0]), p[1], int.Parse(p[2])));\n            loaded++;\n        }\n        return (loaded, skipped);\n    }\n}\n";
R["csb-checkpoint-m14-task"] = "public class Solution\n{\n    public static int SaveNote(string path, int nextId, string title, string body)\n    {\n        string dir = Path.GetDirectoryName(path);\n        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);\n        File.AppendAllText(path, $\"{nextId}|{title}|{body}\" + Environment.NewLine);\n        return nextId + 1;\n    }\n    public static List<(int Id, string Title, string Body)> LoadNotes(string path)\n    {\n        var result = new List<(int, string, string)>();\n        if (!File.Exists(path)) return new List<(int, string, string)>();\n        foreach (string line in File.ReadAllLines(path))\n        {\n            string[] p = line.Split('|');\n            if (p.Length != 3 || !int.TryParse(p[0], out int id)) continue;\n            result.Add((id, p[1], p[2]));\n        }\n        return result;\n    }\n    public static List<(int Id, string Title, string Body)> Search(List<(int Id, string Title, string Body)> notes, string term)\n    {\n        var result = new List<(int, string, string)>();\n        foreach (var n in notes)\n        {\n            if (n.Item2.IndexOf(term, StringComparison.OrdinalIgnoreCase) >= 0\n                || n.Item3.IndexOf(term, StringComparison.OrdinalIgnoreCase) >= 0)\n                result.Add(n);\n        }\n        return result;\n    }\n}\n";
W["csb-checkpoint-m14-task"] = "public class Solution\n{\n    public static int SaveNote(string path, int nextId, string title, string body)\n    {\n        string dir = Path.GetDirectoryName(path);\n        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);\n        File.AppendAllText(path, $\"{nextId}|{title}|{body}\" + Environment.NewLine);\n        return nextId + 1;\n    }\n    public static List<(int Id, string Title, string Body)> LoadNotes(string path)\n    {\n        var result = new List<(int, string, string)>();\n        if (!File.Exists(path)) return new List<(int, string, string)>();\n        foreach (string line in File.ReadAllLines(path))\n        {\n            string[] p = line.Split('|');\n            if (p.Length != 3 || !int.TryParse(p[0], out int id)) continue;\n            result.Add((id, p[1], p[2]));\n        }\n        return result;\n    }\n    public static List<(int Id, string Title, string Body)> Search(List<(int Id, string Title, string Body)> notes, string term)\n    {\n        var result = new List<(int, string, string)>();\n        foreach (var n in notes)\n        {\n            // near-miss: case-SENSITIVE search \u2014 \"oat\" misses \"OAT milk\"\n            if (n.Item2.Contains(term) || n.Item3.Contains(term))\n                result.Add(n);\n        }\n        return result;\n    }\n}\n";
