R["csb-p15-aggregates"] = "public class Solution\n{\n    public static (int Count, int Total, double Average) Stats(IEnumerable<int> nums)\n    {\n        if (nums == null) return (0, 0, 0.0);\n        var list = nums.ToList();\n        if (list.Count == 0) return (0, 0, 0.0);\n        return (list.Count, list.Sum(), list.Average());\n    }\n    public static bool AllPositive(IEnumerable<int> nums)\n    {\n        if (nums == null) return true;\n        return nums.All(n => n > 0);\n    }\n    public static int FirstBig(IEnumerable<int> nums, int threshold)\n    {\n        if (nums == null) return -1;\n        foreach (int n in nums)\n        {\n            if (n > threshold) return n;\n        }\n        return -1;\n    }\n}\n";
