R["csb-checkpoint-m15-task"] = "public class Solution\n{\n    public sealed record Sale(string Region, string Product, int Amount);\n    public static List<string> BigSales(List<Sale> sales, int min)\n    {\n        if (sales == null) return new List<string>();\n        return sales.Where(s => s.Amount >= min)\n                    .OrderByDescending(s => s.Amount).ThenBy(s => s.Product)\n                    .Select(s => $\"{s.Product}:{s.Amount}\")\n                    .ToList();\n    }\n    public static Dictionary<string, int> TotalByRegion(List<Sale> sales)\n    {\n        var result = new Dictionary<string, int>();\n        if (sales == null) return result;\n        foreach (Sale s in sales)\n        {\n            // merge case-insensitively, keep the first-seen casing as the key\n            string key = result.Keys.FirstOrDefault(k => string.Equals(k, s.Region, StringComparison.OrdinalIgnoreCase)) ?? s.Region;\n            result[key] = result.GetValueOrDefault(key) + s.Amount;\n        }\n        return result;\n    }\n    public static (string Product, int Total)? TopProduct(List<Sale> sales)\n    {\n        if (sales == null || sales.Count == 0) return null;\n        return sales.GroupBy(s => s.Product)\n                    .Select(g => (Product: g.Key, Total: g.Sum(x => x.Amount)))\n                    .OrderByDescending(x => x.Total)\n                    .Select(x => ((string Product, int Total)?)x)\n                    .First();\n    }\n    public static double AverageSale(List<Sale> sales, string region)\n    {\n        if (sales == null) return 0.0;\n        var match = sales.Where(s => string.Equals(s.Region, region, StringComparison.OrdinalIgnoreCase)).ToList();\n        if (match.Count == 0) return 0.0;\n        return match.Average(s => (double)s.Amount);\n    }\n}\n";
W["csb-checkpoint-m15-task"] = "public class Solution\n{\n    public sealed record Sale(string Region, string Product, int Amount);\n    public static List<string> BigSales(List<Sale> sales, int min)\n    {\n        if (sales == null) return new List<string>();\n        // near-miss: strict > instead of >= \u2014 a sale exactly at min is\n        // silently excluded from \"big\"\n        return sales.Where(s => s.Amount > min)\n                    .OrderByDescending(s => s.Amount).ThenBy(s => s.Product)\n                    .Select(s => $\"{s.Product}:{s.Amount}\")\n                    .ToList();\n    }\n    public static Dictionary<string, int> TotalByRegion(List<Sale> sales)\n    {\n        var result = new Dictionary<string, int>();\n        if (sales == null) return result;\n        foreach (Sale s in sales)\n        {\n            // near-miss: case-sensitive region keys \u2014 \"North\" and \"north\"\n            // become separate regions\n            result[s.Region] = result.GetValueOrDefault(s.Region) + s.Amount;\n        }\n        return result;\n    }\n    public static (string Product, int Total)? TopProduct(List<Sale> sales)\n    {\n        if (sales == null || sales.Count == 0) return null;\n        return sales.GroupBy(s => s.Product)\n                    .Select(g => (Product: g.Key, Total: g.Sum(x => x.Amount)))\n                    .OrderByDescending(x => x.Total)\n                    .Select(x => ((string Product, int Total)?)x)\n                    .First();\n    }\n    public static double AverageSale(List<Sale> sales, string region)\n    {\n        if (sales == null) return 0.0;\n        var match = sales.Where(s => string.Equals(s.Region, region, StringComparison.OrdinalIgnoreCase)).ToList();\n        if (match.Count == 0) return 0.0;\n        return match.Average(s => (double)s.Amount);\n    }\n}\n";
