W["csb-p16-eventbus"] = "public class Solution\n{\n    public sealed class EventBus\n    {\n        private readonly List<Action<string>> handlers = new List<Action<string>>();\n        public event Action<string>? OnMessage;\n        public void Subscribe(Action<string> handler)\n        {\n            handlers.Add(handler);\n            // near-miss: ASSIGNMENT instead of combination \u2014 every new\n            // subscriber silently REPLACES the previous one, so only the\n            // latest handler ever fires\n            OnMessage = handler;\n        }\n        public void Unsubscribe(Action<string> handler)\n        {\n            handlers.Remove(handler);\n            OnMessage -= handler;\n        }\n        public void Publish(string message)\n        {\n            OnMessage?.Invoke(message);\n        }\n    }\n}\n";
R["csb-checkpoint-m16-task"] = "public class Solution\n{\n    public sealed class AlarmSystem\n    {\n        private readonly Dictionary<string, int> armed = new Dictionary<string, int>();\n        public event Action<string, int>? Triggered;\n        public void Arm(string sensor, int threshold)\n        {\n            armed[sensor] = threshold;\n        }\n        public void Disarm(string sensor)\n        {\n            armed.Remove(sensor);\n        }\n        public void Reading(string sensor, int value)\n        {\n            if (armed.TryGetValue(sensor, out int threshold) && value >= threshold)\n                Triggered?.Invoke(sensor, value);\n        }\n    }\n    public static List<int> LevelsAbove(List<int> readings, int threshold)\n    {\n        if (readings == null) return new List<int>();\n        return readings.Where(v => v > threshold).ToList();\n    }\n    public static Func<int, int> MakeAverager()\n    {\n        long total = 0;\n        int count = 0;\n        return value =>\n        {\n            total += value;\n            count++;\n            return (int)(total / count);\n        };\n    }\n}\n";
W["csb-checkpoint-m16-task"] = "public class Solution\n{\n    public sealed class AlarmSystem\n    {\n        private readonly Dictionary<string, int> armed = new Dictionary<string, int>();\n        public event Action<string, int>? Triggered;\n        public void Arm(string sensor, int threshold)\n        {\n            armed[sensor] = threshold;\n        }\n        public void Disarm(string sensor)\n        {\n            // near-miss: disarm does nothing \u2014 the sensor keeps firing after\n            // being disarmed, silently violating the lifecycle\n        }\n        public void Reading(string sensor, int value)\n        {\n            if (armed.TryGetValue(sensor, out int threshold) && value >= threshold)\n                Triggered?.Invoke(sensor, value);\n        }\n    }\n    public static List<int> LevelsAbove(List<int> readings, int threshold)\n    {\n        if (readings == null) return new List<int>();\n        return readings.Where(v => v > threshold).ToList();\n    }\n    // near-miss: averager state in STATIC fields \u2014 every averager\n    // shares one running total, so independent closures are impossible\n    private static long _total;\n    private static int _count;\n    public static Func<int, int> MakeAverager()\n    {\n        return value =>\n        {\n            _total += value;\n            _count++;\n            return (int)(_total / _count);\n        };\n    }\n}\n";
