R["csb-p17-firstdistinct"] = "public class Solution\n{\n    public static int FirstDistinct(int[] nums)\n    {\n        if (nums == null || nums.Length == 0) return -1;\n        for (int i = 1; i < nums.Length; i++)\n        {\n            bool differsFromAll = true;\n            for (int j = 0; j < i; j++)\n            {\n                if (nums[j] == nums[i]) { differsFromAll = false; break; }\n            }\n            if (differsFromAll) return nums[i];\n        }\n        return -1;\n    }\n}\n";
W["csb-p17-firstdistinct"] = "public class Solution\n{\n    public static int FirstDistinct(int[] nums)\n    {\n        if (nums == null || nums.Length == 0) return -1;\n        // near-miss: misreads the spec as \"first element occurring exactly\n        // once in the whole array\" - global uniqueness instead of\n        // distinct-from-prefix; {7} wrongly yields 7, {3,1} yields 3\n        for (int i = 0; i < nums.Length; i++)\n        {\n            bool unique = true;\n            for (int j = 0; j < nums.Length; j++)\n            {\n                if (j != i && nums[j] == nums[i]) { unique = false; break; }\n            }\n            if (unique) return nums[i];\n        }\n        return -1;\n    }\n}\n";
