R["csb-checkpoint-m17-task"] = "public class Solution\n{\n    public static bool IsValidUsername(string s)\n    {\n        if (s == null) return false;\n        if (s.Length < 3 || s.Length > 20) return false;\n        foreach (char c in s)\n        {\n            if (!char.IsLetterOrDigit(c) && c != '_') return false;\n        }\n        return true;\n    }\n    public static int ParsePort(string input)\n    {\n        if (input == null) throw new ArgumentException(\"input required\");\n        if (!int.TryParse(input, out int port))\n            throw new FormatException(\"not a number\");\n        if (port < 1 || port > 65535)\n            throw new ArgumentOutOfRangeException(\"port outside 1-65535\");\n        return port;\n    }\n    public static List<int> DedupeSorted(List<int> nums)\n    {\n        if (nums == null) return new List<int>();\n        return nums.Distinct().OrderBy(n => n).ToList();\n    }\n}\n";
W["csb-checkpoint-m17-task"] = "public class Solution\n{\n    public static bool IsValidUsername(string s)\n    {\n        if (s == null) return false;\n        // near-miss: length bounds off by one \u2014 2-char and 21-char names pass\n        if (s.Length < 2 || s.Length > 21) return false;\n        foreach (char c in s)\n        {\n            if (!char.IsLetterOrDigit(c) && c != '_') return false;\n        }\n        return true;\n    }\n    public static int ParsePort(string input)\n    {\n        if (input == null) throw new ArgumentException(\"input required\");\n        if (!int.TryParse(input, out int port))\n            throw new FormatException(\"not a number\");\n        if (port < 1 || port > 65535)\n            throw new ArgumentOutOfRangeException(\"port outside 1-65535\");\n        return port;\n    }\n    public static List<int> DedupeSorted(List<int> nums)\n    {\n        if (nums == null) return new List<int>();\n        return nums.Distinct().OrderBy(n => n).ToList();\n    }\n}\n";
R["csb-p18-csproj-parse"] = "public class Solution\n{\n    public static string? GetProperty(string csprojXml, string tag)\n    {\n        string open = \"<\" + tag + \">\";\n        string close = \"</\" + tag + \">\";\n        int i = csprojXml.IndexOf(open, StringComparison.Ordinal);\n        if (i < 0) return null;\n        int start = i + open.Length;\n        int end = csprojXml.IndexOf(close, start, StringComparison.Ordinal);\n        if (end < 0) return null;\n        return csprojXml.Substring(start, end - start);\n    }\n    public static bool IsExecutable(string csprojXml)\n    {\n        return csprojXml.IndexOf(\"<OutputType>Exe</OutputType>\", StringComparison.OrdinalIgnoreCase) >= 0;\n    }\n}\n";
W["csb-p18-csproj-parse"] = "public class Solution\n{\n    public static string? GetProperty(string csprojXml, string tag)\n    {\n        string open = \"<\" + tag + \">\";\n        string close = \"</\" + tag + \">\";\n        int i = csprojXml.IndexOf(open, StringComparison.Ordinal);\n        if (i < 0) return null;\n        int start = i + open.Length;\n        int end = csprojXml.IndexOf(close, start, StringComparison.Ordinal);\n        if (end < 0) return null;\n        return csprojXml.Substring(start, end - start);\n    }\n    public static bool IsExecutable(string csprojXml)\n    {\n        // near-miss: case-SENSITIVE match \u2014 a hand-edited csproj with\n        // lowercase \"exe\" is misclassified as a library\n        return csprojXml.IndexOf(\"<OutputType>Exe</OutputType>\", StringComparison.Ordinal) >= 0;\n    }\n}\n";
R["csb-p18-deps"] = "public class Solution\n{\n    public static List<string> BuildOrder(List<(string Project, string DependsOn)> refs, List<string> all)\n    {\n        var remaining = new List<string>(all);\n        var result = new List<string>();\n        while (remaining.Count > 0)\n        {\n            var ready = remaining\n                .Where(p => !refs.Any(r => r.Project == p && remaining.Contains(r.DependsOn)))\n                .OrderBy(p => p, StringComparer.Ordinal)\n                .ToList();\n            if (ready.Count == 0) return result;   // cycle guard (not graded)\n            foreach (string p in ready)\n            {\n                result.Add(p);\n                remaining.Remove(p);\n            }\n        }\n        return result;\n    }\n}\n";
W["csb-p18-deps"] = "public class Solution\n{\n    public static List<string> BuildOrder(List<(string Project, string DependsOn)> refs, List<string> all)\n    {\n        var remaining = new List<string>(all);\n        var result = new List<string>();\n        while (remaining.Count > 0)\n        {\n            var ready = remaining\n                // near-miss: picks projects whose dependencies are merely\n                // LISTED anywhere (not still remaining) \u2014 projects scheduled\n                // before their dependencies are ready\n                .Where(p => !refs.Any(r => r.Project == p))\n                .OrderBy(p => p, StringComparer.Ordinal)\n                .ToList();\n            if (ready.Count == 0) return result;\n            foreach (string p in ready)\n            {\n                result.Add(p);\n                remaining.Remove(p);\n            }\n        }\n        return result;\n    }\n}\n";
R["csb-p18-verbs"] = "public class Solution\n{\n    public static (bool Compiles, bool Runs, bool Packages) VerbEffect(string verb)\n    {\n        switch (verb)\n        {\n            case \"build\": return (true, false, false);\n            case \"run\": return (true, true, false);\n            case \"publish\": return (true, true, true);\n            case \"test\": return (true, false, false);\n            default: throw new ArgumentException(\"unknown verb\");\n        }\n    }\n}\n";
W["csb-p18-verbs"] = "public class Solution\n{\n    public static (bool Compiles, bool Runs, bool Packages) VerbEffect(string verb)\n    {\n        switch (verb)\n        {\n            // near-miss: \"run\" marked as not compiling \u2014 but dotnet run\n            // builds first, then executes\n            case \"build\": return (true, false, false);\n            case \"run\": return (false, true, false);\n            case \"publish\": return (true, true, true);\n            case \"test\": return (true, false, false);\n            default: throw new ArgumentException(\"unknown verb\");\n        }\n    }\n}\n";
