R["csb-checkpoint-m18-task"] = "public class Solution\n{\n    public static bool HasCycle(List<(string Project, string DependsOn)> refs)\n    {\n        var map = new Dictionary<string, List<string>>();\n        foreach (var r in refs)\n        {\n            if (!map.TryGetValue(r.Project, out var list)) map[r.Project] = list = new List<string>();\n            list.Add(r.DependsOn);\n        }\n        var visiting = new HashSet<string>();\n        var done = new HashSet<string>();\n        bool Dfs(string node)\n        {\n            if (done.Contains(node)) return false;\n            if (!visiting.Add(node)) return true;\n            if (map.TryGetValue(node, out var deps))\n            {\n                foreach (string d in deps)\n                {\n                    if (Dfs(d)) return true;\n                }\n            }\n            visiting.Remove(node);\n            done.Add(node);\n            return false;\n        }\n        foreach (string node in map.Keys)\n        {\n            if (Dfs(node)) return true;\n        }\n        return false;\n    }\n    public static string ScaffoldCommand(string kind, string name)\n    {\n        switch (kind)\n        {\n            case \"console\": return $\"dotnet new console -o {name}\";\n            case \"classlib\": return $\"dotnet new classlib -o {name}\";\n            default: throw new ArgumentException(\"unknown project kind\");\n        }\n    }\n    public static List<string> FailingProjects(List<(string Project, string DependsOn)> refs, List<string> broken)\n    {\n        var brokenSet = new HashSet<string>(broken);\n        bool changed = true;\n        while (changed)\n        {\n            changed = false;\n            foreach (var r in refs)\n            {\n                if (brokenSet.Contains(r.DependsOn) && brokenSet.Add(r.Project)) changed = true;\n            }\n        }\n        return brokenSet.OrderBy(p => p, StringComparer.Ordinal).ToList();\n    }\n}\n";
W["csb-checkpoint-m18-task"] = "public class Solution\n{\n    public static bool HasCycle(List<(string Project, string DependsOn)> refs)\n    {\n        var map = new Dictionary<string, List<string>>();\n        foreach (var r in refs)\n        {\n            if (!map.TryGetValue(r.Project, out var list)) map[r.Project] = list = new List<string>();\n            list.Add(r.DependsOn);\n        }\n        var visiting = new HashSet<string>();\n        var done = new HashSet<string>();\n        bool Dfs(string node)\n        {\n            if (done.Contains(node)) return false;\n            // near-miss: marks visited without removing on exit \u2014 a diamond\n            // graph (two paths to the same node) is misreported as a cycle\n            if (!visiting.Add(node)) return true;\n            if (map.TryGetValue(node, out var deps))\n            {\n                foreach (string d in deps)\n                {\n                    if (Dfs(d)) return true;\n                }\n            }\n            return false;\n        }\n        foreach (string node in map.Keys)\n        {\n            if (Dfs(node)) return true;\n        }\n        return false;\n    }\n    public static string ScaffoldCommand(string kind, string name)\n    {\n        switch (kind)\n        {\n            case \"console\": return $\"dotnet new console -o {name}\";\n            case \"classlib\": return $\"dotnet new classlib -o {name}\";\n            default: throw new ArgumentException(\"unknown project kind\");\n        }\n    }\n    public static List<string> FailingProjects(List<(string Project, string DependsOn)> refs, List<string> broken)\n    {\n        var brokenSet = new HashSet<string>(broken);\n        bool changed = true;\n        while (changed)\n        {\n            changed = false;\n            foreach (var r in refs)\n            {\n                if (brokenSet.Contains(r.DependsOn) && brokenSet.Add(r.Project)) changed = true;\n            }\n        }\n        return brokenSet.OrderBy(p => p, StringComparer.Ordinal).ToList();\n    }\n}\n";
R["csb-p19-graph"] = "public class Solution\n{\n    public static List<string> History(Dictionary<string, string> parent, string head)\n    {\n        if (!parent.ContainsKey(head))\n            throw new ArgumentException(\"unknown head\");\n        var result = new List<string>();\n        string? current = head;\n        while (current != null)\n        {\n            result.Add(current);\n            current = parent[current];\n        }\n        return result;\n    }\n}\n";
W["csb-p19-graph"] = "public class Solution\n{\n    public static List<string> History(Dictionary<string, string> parent, string head)\n    {\n        if (!parent.ContainsKey(head))\n            throw new ArgumentException(\"unknown head\");\n        var result = new List<string>();\n        string? current = head;\n        // near-miss: builds the list then REVERSES it \u2014 oldest first,\n        // contradicting the newest-first contract\n        while (current != null)\n        {\n            result.Add(current);\n            current = parent[current];\n        }\n        result.Reverse();\n        return result;\n    }\n}\n";
R["csb-p19-merge"] = "public class Solution\n{\n    public static string? CommonAncestor(Dictionary<string, string> parent, string a, string b)\n    {\n        var ancestors = new HashSet<string>();\n        string? cur = a;\n        while (cur != null) { ancestors.Add(cur); cur = parent[cur]; }\n        cur = b;\n        while (cur != null)\n        {\n            if (ancestors.Contains(cur)) return cur;\n            cur = parent[cur];\n        }\n        return null;\n    }\n}\n";
W["csb-p19-merge"] = "public class Solution\n{\n    public static string? CommonAncestor(Dictionary<string, string> parent, string a, string b)\n    {\n        var ancestors = new HashSet<string>();\n        string? cur = a;\n        while (cur != null) { ancestors.Add(cur); cur = parent[cur]; }\n        // near-miss: does not test b's chain's START before stepping \u2014 when\n        // b itself is the ancestor, the walk skips it and keeps climbing\n        cur = parent[b];\n        while (cur != null)\n        {\n            if (ancestors.Contains(cur)) return cur;\n            cur = parent[cur];\n        }\n        return null;\n    }\n}\n";
R["csb-p19-ignore"] = "public class Solution\n{\n    public static bool IsIgnored(string path, List<string> rules)\n    {\n        bool ignored = false;\n        foreach (string rule in rules)\n        {\n            if (rule.StartsWith(\"!\"))\n            {\n                string target = rule.Substring(1);\n                if (Matches(path, target)) ignored = false;\n            }\n            else if (Matches(path, rule))\n            {\n                ignored = true;\n            }\n        }\n        return ignored;\n    }\n    private static bool Matches(string path, string rule)\n    {\n        if (rule.EndsWith(\"/\")) return path.StartsWith(rule, StringComparison.Ordinal);\n        if (rule.StartsWith(\"*.\")) return path.EndsWith(rule.Substring(1), StringComparison.Ordinal);\n        return path == rule || path.EndsWith(\"/\" + rule, StringComparison.Ordinal);\n    }\n}\n";
W["csb-p19-ignore"] = "public class Solution\n{\n    public static bool IsIgnored(string path, List<string> rules)\n    {\n        // near-miss: FIRST matching rule wins \u2014 negations placed later never\n        // get a chance, breaking git's last-match-wins semantic\n        foreach (string rule in rules)\n        {\n            if (rule.StartsWith(\"!\"))\n            {\n                string target = rule.Substring(1);\n                if (Matches(path, target)) return false;\n            }\n            else if (Matches(path, rule))\n            {\n                return true;\n            }\n        }\n        return false;\n    }\n    private static bool Matches(string path, string rule)\n    {\n        if (rule.EndsWith(\"/\")) return path.StartsWith(rule, StringComparison.Ordinal);\n        if (rule.StartsWith(\"*.\")) return path.EndsWith(rule.Substring(1), StringComparison.Ordinal);\n        return path == rule || path.EndsWith(\"/\" + rule, StringComparison.Ordinal);\n    }\n}\n";
R["csb-p19-message"] = "public class Solution\n{\n    public static string? ValidateMessage(string message)\n    {\n        if (string.IsNullOrEmpty(message)) return \"empty\";\n        if (message.Length > 72) return \"too-long\";\n        if (message.EndsWith(\".\")) return \"trailing-period\";\n        if (char.IsLower(message[0])) return \"lowercase-start\";\n        return null;\n    }\n}\n";
W["csb-p19-message"] = "public class Solution\n{\n    public static string? ValidateMessage(string message)\n    {\n        if (string.IsNullOrEmpty(message)) return \"empty\";\n        // near-miss: 72 treated as INCLUSIVE upper bound but strict < used \u2014\n        // a 72-char message is wrongly rejected as too-long\n        if (message.Length >= 72) return \"too-long\";\n        if (message.EndsWith(\".\")) return \"trailing-period\";\n        if (char.IsLower(message[0])) return \"lowercase-start\";\n        return null;\n    }\n}\n";
R["csb-checkpoint-m19-task"] = "public class Solution\n{\n    public static bool IsLinear(List<string> commits)\n    {\n        var seen = new HashSet<string>();\n        foreach (string c in commits)\n        {\n            if (!seen.Add(c)) return false;\n        }\n        return true;\n    }\n    public static string DescribeChange(string before, string after)\n    {\n        if (before.Length == 0) return \"added\";\n        if (after.Length == 0) return \"removed\";\n        return \"modified\";\n    }\n    public static List<string> StaleBranches(Dictionary<string, string> branchTip, string mainTip, List<string> mergedIntoMain)\n    {\n        var merged = new HashSet<string>(mergedIntoMain);\n        var result = new List<string>();\n        foreach (var kv in branchTip)\n        {\n            if (kv.Value != mainTip && !merged.Contains(kv.Key))\n                result.Add(kv.Key);\n        }\n        result.Sort(StringComparer.Ordinal);\n        return result;\n    }\n}\n";
W["csb-checkpoint-m19-task"] = "public class Solution\n{\n    public static bool IsLinear(List<string> commits)\n    {\n        var seen = new HashSet<string>();\n        foreach (string c in commits)\n        {\n            if (!seen.Add(c)) return false;\n        }\n        return true;\n    }\n    public static string DescribeChange(string before, string after)\n    {\n        if (before.Length == 0) return \"added\";\n        if (after.Length == 0) return \"removed\";\n        return \"modified\";\n    }\n    public static List<string> StaleBranches(Dictionary<string, string> branchTip, string mainTip, List<string> mergedIntoMain)\n    {\n        var merged = new HashSet<string>(mergedIntoMain);\n        var result = new List<string>();\n        foreach (var kv in branchTip)\n        {\n            // near-miss: treats a branch AT main's tip as stale too \u2014\n            // synchronized branches should never be flagged\n            if (!merged.Contains(kv.Key))\n                result.Add(kv.Key);\n        }\n        result.Sort(StringComparer.Ordinal);\n        return result;\n    }\n}\n";
R["csb-p20-firstdup"] = "public class Solution\n{\n    public static int FirstDuplicate(int[] nums)\n    {\n        var seen = new HashSet<int>();\n        foreach (int n in nums)\n        {\n            if (!seen.Add(n)) return n;\n        }\n        return -1;\n    }\n}\n";
W["csb-p20-firstdup"] = "public class Solution\n{\n    public static int FirstDuplicate(int[] nums)\n    {\n        // near-miss: compares only ADJACENT pairs \u2014 a duplicate that is\n        // not next to its twin goes unnoticed\n        for (int i = 0; i + 1 < nums.Length; i++)\n        {\n            if (nums[i] == nums[i + 1]) return nums[i];\n        }\n        return -1;\n    }\n}\n";
R["csb-p20-binsearch"] = "public class Solution\n{\n    public static int BinarySearch(int[] sorted, int target)\n    {\n        int lo = 0, hi = sorted.Length - 1;\n        while (lo <= hi)\n        {\n            int mid = lo + (hi - lo) / 2;\n            if (sorted[mid] == target) return mid;\n            if (sorted[mid] < target) lo = mid + 1;\n            else hi = mid - 1;\n        }\n        return -1;\n    }\n}\n";
W["csb-p20-binsearch"] = "public class Solution\n{\n    public static int BinarySearch(int[] sorted, int target)\n    {\n        int lo = 0, hi = sorted.Length - 1;\n        // near-miss: strict < \u2014 when the window shrinks to ONE element\n        // (lo == hi) it is never examined, so a final-position target\n        // is reported missing\n        while (lo < hi)\n        {\n            int mid = lo + (hi - lo) / 2;\n            if (sorted[mid] == target) return mid;\n            if (sorted[mid] < target) lo = mid + 1;\n            else hi = mid - 1;\n        }\n        return -1;\n    }\n}\n";
R["csb-p20-freq"] = "public class Solution\n{\n    public static string TopWord(List<string> words)\n    {\n        var counts = new Dictionary<string, int>();\n        foreach (string w in words)\n        {\n            counts[w] = counts.GetValueOrDefault(w) + 1;\n        }\n        string best = \"\";\n        int bestCount = -1;\n        foreach (var kv in counts)\n        {\n            if (kv.Value > bestCount ||\n                (kv.Value == bestCount && string.CompareOrdinal(kv.Key, best) < 0))\n            {\n                best = kv.Key;\n                bestCount = kv.Value;\n            }\n        }\n        return best;\n    }\n}\n";
W["csb-p20-freq"] = "public class Solution\n{\n    public static string TopWord(List<string> words)\n    {\n        var counts = new Dictionary<string, int>();\n        foreach (string w in words)\n        {\n            counts[w] = counts.GetValueOrDefault(w) + 1;\n        }\n        string best = \"\";\n        int bestCount = -1;\n        foreach (var kv in counts)\n        {\n            // near-miss: ties resolved by INSERTION order (first seen\n            // wins) instead of alphabetically\n            if (kv.Value > bestCount)\n            {\n                best = kv.Key;\n                bestCount = kv.Value;\n            }\n        }\n        return best;\n    }\n}\n";
R["csb-p20-paren"] = "public class Solution\n{\n    public static bool IsBalanced(string s)\n    {\n        var stack = new Stack<char>();\n        foreach (char c in s)\n        {\n            if (c == '(' || c == '[' || c == '{')\n            {\n                stack.Push(c);\n            }\n            else if (c == ')' || c == ']' || c == '}')\n            {\n                if (stack.Count == 0) return false;\n                char open = stack.Pop();\n                if ((c == ')' && open != '(') ||\n                    (c == ']' && open != '[') ||\n                    (c == '}' && open != '{'))\n                    return false;\n            }\n        }\n        return stack.Count == 0;\n    }\n}\n";
W["csb-p20-paren"] = "public class Solution\n{\n    public static bool IsBalanced(string s)\n    {\n        // near-miss: counts openers and closers \u2014 nesting and matching\n        // are ignored entirely\n        int opens = 0, closes = 0;\n        foreach (char c in s)\n        {\n            if (c == '(' || c == '[' || c == '{') opens++;\n            else if (c == ')' || c == ']' || c == '}') closes++;\n        }\n        return opens == closes;\n    }\n}\n";
R["csb-checkpoint-m20-task"] = "public class Solution\n{\n    public static int MissingNumber(int[] nums)\n    {\n        int n = nums.Length;\n        long expected = (long)n * (n + 1) / 2;\n        long actual = 0;\n        foreach (int v in nums) actual += v;\n        return (int)(expected - actual);\n    }\n    public static bool HasPairSum(int[] nums, int target)\n    {\n        var seen = new HashSet<int>();\n        foreach (int v in nums)\n        {\n            if (seen.Contains(target - v)) return true;\n            seen.Add(v);\n        }\n        return false;\n    }\n    public static string Compress(string s)\n    {\n        if (s.Length == 0) return \"\";\n        var sb = new System.Text.StringBuilder();\n        int run = 1;\n        for (int i = 1; i < s.Length; i++)\n        {\n            if (s[i] == s[i - 1]) run++;\n            else\n            {\n                sb.Append(s[i - 1]).Append(run);\n                run = 1;\n            }\n        }\n        sb.Append(s[s.Length - 1]).Append(run);\n        return sb.ToString();\n    }\n}\n";
W["csb-checkpoint-m20-task"] = "public class Solution\n{\n    public static int MissingNumber(int[] nums)\n    {\n        // near-miss: treats the range as 0..n+1 (uses Length+1) \u2014 every\n        // answer comes back too large\n        int n = nums.Length + 1;\n        long expected = (long)n * (n + 1) / 2;\n        long actual = 0;\n        foreach (int v in nums) actual += v;\n        return (int)(expected - actual);\n    }\n    public static bool HasPairSum(int[] nums, int target)\n    {\n        // near-miss: compares every pair INCLUDING an element with\n        // itself \u2014 target 8 on [.., 4, ..] \"pairs\" 4 with 4\n        for (int i = 0; i < nums.Length; i++)\n            for (int j = 0; j < nums.Length; j++)\n                if (nums[i] + nums[j] == target) return true;\n        return false;\n    }\n    public static string Compress(string s)\n    {\n        // near-miss: omits counts of 1 \u2014 \"a3b2c1\" becomes \"a3bc\"\n        if (s.Length == 0) return \"\";\n        var sb = new System.Text.StringBuilder();\n        int run = 1;\n        for (int i = 1; i < s.Length; i++)\n        {\n            if (s[i] == s[i - 1]) run++;\n            else\n            {\n                sb.Append(s[i - 1]);\n                if (run > 1) sb.Append(run);\n                run = 1;\n            }\n        }\n        sb.Append(s[s.Length - 1]);\n        if (run > 1) sb.Append(run);\n        return sb.ToString();\n    }\n}\n";
R["csb-p21-validate"] = "public class Solution\n{\n    public static AddResult Validate(Transaction t)\n    {\n        if (t.Amount <= 0m) return new AddResult(false, \"amount-must-be-positive\");\n        if (string.IsNullOrWhiteSpace(t.Category)) return new AddResult(false, \"category-required\");\n        if (t.Description != null && t.Description.Length > 100)\n            return new AddResult(false, \"description-too-long\");\n        return new AddResult(true, null);\n    }\n}\n";
W["csb-p21-validate"] = "public class Solution\n{\n    public static AddResult Validate(Transaction t)\n    {\n        if (t.Amount <= 0m) return new AddResult(false, \"amount-must-be-positive\");\n        // near-miss: checks the description against 10 chars instead of\n        // 100 \u2014 perfectly good descriptions get rejected\n        if (t.Description != null && t.Description.Length > 10)\n            return new AddResult(false, \"description-too-long\");\n        if (string.IsNullOrWhiteSpace(t.Category)) return new AddResult(false, \"category-required\");\n        return new AddResult(true, null);\n    }\n}\n";
R["csb-p21-balance"] = "public class Solution\n{\n    public static List<decimal> RunningBalance(List<Transaction> ledger)\n    {\n        var result = new List<decimal>();\n        decimal balance = 0m;\n        foreach (var t in ledger)\n        {\n            balance += t.Dir == Direction.Income ? t.Amount : -t.Amount;\n            result.Add(balance);\n        }\n        return result;\n    }\n}\n";
W["csb-p21-balance"] = "public class Solution\n{\n    public static List<decimal> RunningBalance(List<Transaction> ledger)\n    {\n        var result = new List<decimal>();\n        // near-miss: never CARRIES the balance \u2014 every entry reports the\n        // effect of its own transaction only\n        foreach (var t in ledger)\n        {\n            result.Add(t.Dir == Direction.Income ? t.Amount : -t.Amount);\n        }\n        return result;\n    }\n}\n";
R["csb-p21-categories"] = "public class Solution\n{\n    public static List<string> TopCategories(List<Transaction> ledger, int n)\n    {\n        return ledger\n            .GroupBy(t => t.Category)\n            .Select(g => new { Category = g.Key, Total = g.Sum(t => t.Amount) })\n            .OrderByDescending(x => x.Total)\n            .ThenBy(x => x.Category, StringComparer.Ordinal)\n            .Select(x => x.Category)\n            .Take(n)\n            .ToList();\n    }\n}\n";
W["csb-p21-categories"] = "public class Solution\n{\n    public static List<string> TopCategories(List<Transaction> ledger, int n)\n    {\n        // near-miss: ranks by COUNT of transactions instead of the SUM\n        // of amounts\n        return ledger\n            .GroupBy(t => t.Category)\n            .Select(g => new { Category = g.Key, Count = g.Count() })\n            .OrderByDescending(x => x.Count)\n            .ThenBy(x => x.Category, StringComparer.Ordinal)\n            .Select(x => x.Category)\n            .Take(n)\n            .ToList();\n    }\n}\n";
R["csb-p21-csv"] = "public class Solution\n{\n    public static string SaveCsv(List<Transaction> ledger, string dir)\n    {\n        Directory.CreateDirectory(dir);\n        string path = Path.Combine(dir, \"ledger.csv\");\n        var lines = new List<string>();\n        foreach (var t in ledger)\n        {\n            lines.Add($\"{t.Id},{(t.Dir == Direction.Income ? \"income\" : \"expense\")},{t.Amount.ToString(System.Globalization.CultureInfo.InvariantCulture)},{t.Category}\");\n        }\n        File.WriteAllLines(path, lines);\n        return path;\n    }\n}\n";
W["csb-p21-csv"] = "public class Solution\n{\n    public static string SaveCsv(List<Transaction> ledger, string dir)\n    {\n        // near-miss: forgets to create the directory \u2014 throws\n        // DirectoryNotFoundException on a fresh dir\n        string path = Path.Combine(dir, \"ledger.csv\");\n        var lines = new List<string>();\n        foreach (var t in ledger)\n        {\n            lines.Add($\"{t.Id},{(t.Dir == Direction.Income ? \"income\" : \"expense\")},{t.Amount.ToString(System.Globalization.CultureInfo.InvariantCulture)},{t.Category}\");\n        }\n        File.WriteAllLines(path, lines);\n        return path;\n    }\n}\n";
R["csb-checkpoint-m21-task"] = "public class Solution\n{\n    public record Statement(decimal Income, decimal Expense, decimal Balance, List<string> Top);\n    public static Statement MonthStatement(List<Transaction> ledger, int year, int month)\n    {\n        var inMonth = ledger\n            .Where(t => t.Date.Year == year && t.Date.Month == month)\n            .ToList();\n        decimal income = inMonth.Where(t => t.Dir == Direction.Income).Sum(t => t.Amount);\n        decimal expense = inMonth.Where(t => t.Dir == Direction.Expense).Sum(t => t.Amount);\n        var top = inMonth\n            .OrderByDescending(t => t.Amount)\n            .Select(t => t.Description)\n            .Take(3)\n            .ToList();\n        return new Statement(income, expense, income - expense, top);\n    }\n}\n";
W["csb-checkpoint-m21-task"] = "public class Solution\n{\n    public record Statement(decimal Income, decimal Expense, decimal Balance, List<string> Top);\n    public static Statement MonthStatement(List<Transaction> ledger, int year, int month)\n    {\n        // near-miss: checks only the MONTH \u2014 April (month 4) leaks into\n        // a May (month 5) statement of a different year\n        var inMonth = ledger\n            .Where(t => t.Date.Month == month)\n            .ToList();\n        decimal income = inMonth.Where(t => t.Dir == Direction.Income).Sum(t => t.Amount);\n        decimal expense = inMonth.Where(t => t.Dir == Direction.Expense).Sum(t => t.Amount);\n        var top = inMonth\n            .OrderByDescending(t => t.Amount)\n            .Select(t => t.Description)\n            .Take(3)\n            .ToList();\n        return new Statement(income, expense, income - expense, top);\n    }\n}\n";
